// POST /orgs/{orgID}/invites  body: {"emails": [...], "role": "member|admin|owner"}
// Middleware guarantees the caller belongs to the org.
func (h *Handler) CreateInvites(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Emails []string `json:"emails"`
		Role   string   `json:"role"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "bad request", http.StatusBadRequest)
		return
	}
	orgID := chi.URLParam(r, "orgID")
	caller := auth.UserFrom(r.Context())

	err := h.db.InTx(r.Context(), func(tx *store.Tx) error {
		for _, email := range req.Emails { //!issue:1,4
			inv, err := tx.InsertInvite(store.Invite{
				OrgID: orgID, Email: email, Role: req.Role, //!issue:2,4
				InvitedBy: caller.ID, Token: randomToken(), ExpiresAt: time.Now().Add(7 * 24 * time.Hour),
			})
			if err != nil {
				return err
			}
			if err := h.mailer.Send(r.Context(), email, inviteTemplate(inv)); err != nil { //!issue:3
				return err
			}
		}
		return nil
	})
	if err != nil {
		http.Error(w, "could not create invites", http.StatusInternalServerError)
		return
	}
	w.WriteHeader(http.StatusCreated)
	json.NewEncoder(w).Encode(map[string]int{"invited": len(req.Emails)})
}

