    this.http = new HttpClient({ baseUrl: "https://treasury.internal/fx", timeoutMs: 5000 }); //!issue:1
    void this.refresh(); //!issue:1
    setInterval(() => void this.refresh(), 5 * 60_000); //!issue:3
  }

