      const res = await this.http.get<Record<string, number>>("/latest?base=USD");
      this.rates = res.body;
    } catch { //!issue:4
      // keep the previous rates
    }
  }

  async quote(sku: string, currency: string): Promise<Money> {
    const usd = await this.db.priceFor(sku);
    const rate = this.rates[currency] ?? 1; //!issue:2
