type PricingService struct {
	db    PriceStore
	http  *http.Client
	rates atomic.Pointer[map[string]float64]
}

func NewPricingService(db PriceStore) *PricingService {
	s := &PricingService{db: db, http: &http.Client{Timeout: 5 * time.Second}} //!issue:1
	s.rates.Store(&map[string]float64{})
	go func() { //!issue:1,3
		for {
			s.refresh()
			time.Sleep(5 * time.Minute)
		}
	}()
	return s
}

func (s *PricingService) refresh() {
	resp, err := s.http.Get("https://treasury.internal/fx/latest?base=USD")
	if err != nil {
		return //!issue:4
	}
	defer resp.Body.Close()
	var latest map[string]float64
	if err := json.NewDecoder(resp.Body).Decode(&latest); err != nil {
		return //!issue:4
	}
	s.rates.Store(&latest)
}

func (s *PricingService) Quote(ctx context.Context, sku, currency string) (Money, error) {
	usd, err := s.db.PriceFor(ctx, sku)
	if err != nil {
		return Money{}, err
	}
	rate, ok := (*s.rates.Load())[currency]
	if !ok {
		rate = 1 //!issue:2
	}
	return usd.Convert(currency, rate), nil
}

