pub struct PricingService {
    db: Arc<dyn PriceStore>,
    rates: Arc<RwLock<HashMap<String, f64>>>,
}

impl PricingService {
    pub fn new(db: Arc<dyn PriceStore>) -> Self {
        let rates = Arc::new(RwLock::new(HashMap::new()));
        let client = reqwest::Client::new(); //!issue:1
        let shared = Arc::clone(&rates);
        tokio::spawn(async move { //!issue:1,3
            let mut tick = tokio::time::interval(Duration::from_secs(300));
            loop {
                tick.tick().await;
                let fetched = match client.get("https://treasury.internal/fx/latest?base=USD").send().await {
                    Ok(resp) => resp.json::<HashMap<String, f64>>().await,
                    Err(e) => Err(e),
                };
                if let Ok(latest) = fetched { //!issue:4
                    *shared.write().unwrap() = latest;
                }
            }
        });
        Self { db, rates }
    }

    pub async fn quote(&self, sku: &str, currency: &str) -> Result<Money, PricingError> {
        let usd = self.db.price_for(sku).await?;
        let rate = self.rates.read().unwrap().get(currency).copied().unwrap_or(1.0); //!issue:2
        Ok(usd.convert(currency, rate))
    }
}

