@Service
public class PricingService {
    private final PriceStore db;
    private final HttpClient http = HttpClient.newHttpClient(); //!issue:1
    private final ScheduledExecutorService scheduler = Executors.newSingleThreadScheduledExecutor(); //!issue:3
    private volatile Map<String, BigDecimal> rates = Map.of();

    public PricingService(PriceStore db) {
        this.db = db;
        scheduler.scheduleAtFixedRate(this::refresh, 0, 5, TimeUnit.MINUTES); //!issue:1,3
    }

    private void refresh() {
        try {
            HttpRequest req = HttpRequest.newBuilder(URI.create("https://treasury.internal/fx/latest?base=USD")).build();
            String body = http.send(req, HttpResponse.BodyHandlers.ofString()).body();
            rates = Json.parseRates(body);
        } catch (Exception e) { //!issue:4
            // keep the previous rates
        }
    }

    public Money quote(String sku, String currency) {
        Money usd = db.priceFor(sku);
        BigDecimal rate = rates.getOrDefault(currency, BigDecimal.ONE); //!issue:2
        return Money.convert(usd, currency, rate);
    }
}

