const DAY_MS = 86_400_000;
const TRIAL_DAYS = 14; //!issue:4

export function trialDaysLeft(account: Account): number {
  const endsAt = account.trialStartedAt.getTime() + TRIAL_DAYS * DAY_MS; //!issue:4
  return Math.floor((endsAt - Date.now()) / DAY_MS); //!issue:1,2
}

export function trialBanner(account: Account): Banner | null {
  const left = trialDaysLeft(account);
  if (left <= 0) return { kind: "paywall" }; //!issue:2
  if (left <= 3) return { kind: "warning", text: `${left} days left in your trial` };
  return null;
}

// trial.test.ts
describe("trialBanner", () => {
  it("warns in the last three days", () => {
    const account = { trialStartedAt: new Date("2026-11-04T00:00:00Z") } as Account; //!issue:3
    expect(trialBanner(account)).toEqual({ kind: "warning", text: "2 days left in your trial" }); //!issue:3
  });

  it("shows the paywall after the trial", () => {
    const account = { trialStartedAt: new Date(Date.now() - 15 * DAY_MS) } as Account;
    expect(trialBanner(account)?.kind).toBe("paywall");
  });
});

