const trialDays = 14 //!issue:4

func TrialDaysLeft(a Account) int {
	endsAt := a.TrialStartedAt.AddDate(0, 0, trialDays) //!issue:4
	return int(time.Until(endsAt).Hours() / 24) //!issue:1,2
}

