type PageRequest struct {
	Page     int
	PageSize int
}

// ParsePageRequest reads ?page=1&pageSize=50; the UI's first page is page=1.
func ParsePageRequest(q url.Values) PageRequest {
	return PageRequest{Page: atoiOr(q.Get("page"), 1), PageSize: atoiOr(q.Get("pageSize"), 50)} //!issue:3
}

func (p PageRequest) Offset() int { return p.Page * p.PageSize } //!issue:1

func ToPage[T any](items []T, p PageRequest, total int) Page[T] {
	out := Page[T]{Items: items, Page: p.Page, Total: total}
	if len(items) == p.PageSize { //!issue:4
		next := p.Page + 1
		out.NextPage = &next
	}
	return out
}

func (r *AuditRepo) List(ctx context.Context, orgID string, p PageRequest) (Page[AuditEvent], error) {
	var items []AuditEvent
	err := r.db.SelectContext(ctx, &items,
		"SELECT * FROM audit_events WHERE org_id = $1 ORDER BY created_at DESC LIMIT $2 OFFSET $3", //!issue:2
		orgID, p.PageSize, p.Offset())
	if err != nil {
		return Page[AuditEvent]{}, err
	}
	var total int
	if err := r.db.GetContext(ctx, &total, "SELECT count(*) FROM audit_events WHERE org_id = $1", orgID); err != nil { //!issue:4
		return Page[AuditEvent]{}, err
	}
	return ToPage(items, p, total), nil
}

