	totals   map[string]int64
	mu       sync.Mutex
	top      []Entry
}

// Registered with consumer.Subscribe("score.awarded", lb.OnScore, WithConcurrency(8))
func (l *Leaderboard) OnScore(ctx context.Context, evt ScoreAwarded) error {
	prev := l.totals[evt.PlayerID] //!issue:1
	profile, err := l.profiles.Get(ctx, evt.PlayerID) //!issue:5
	if err != nil {
		return err
	}
	total := prev + evt.Points //!issue:2
	l.totals[evt.PlayerID] = total //!issue:1
	l.mu.Lock()
	l.top = append(l.top, Entry{PlayerID: evt.PlayerID, Name: profile.DisplayName, Score: total}) //!issue:3
	sort.Slice(l.top, func(i, j int) bool { return l.top[i].Score > l.top[j].Score })
	if len(l.top) > 10 {
		l.top = l.top[:10]
	}
	l.mu.Unlock()
	return nil
}

func (l *Leaderboard) TopTen() []Entry {
	l.mu.Lock()
	defer l.mu.Unlock()
	return l.top //!issue:4
}

