func (h *Handler) PaymentsWebhook(w http.ResponseWriter, r *http.Request) {
	var event ProviderEvent
	if err := json.NewDecoder(r.Body).Decode(&event); err != nil {
		http.Error(w, "bad payload", http.StatusBadRequest)
		return
	}
	sig := parseSignatureHeader(r.Header.Get("X-Signature")) // map: "t" -> ..., "v1" -> ...
	canonical, _ := json.Marshal(event) //!issue:1
	mac := hmac.New(sha256.New, h.webhookSecret)
	mac.Write([]byte(sig["t"] + "." + string(canonical))) //!issue:1
	if hex.EncodeToString(mac.Sum(nil)) != sig["v1"] { //!issue:1
		http.Error(w, "bad signature", http.StatusUnauthorized)
		return
	}
	ctx := r.Context()
	switch event.Type {
	case "payment.succeeded": //!issue:3
		order, err := h.orders.MarkPaid(ctx, event.Data.OrderID, event.Data.Amount)
		var pdf []byte
		if err == nil {
			pdf, err = h.invoices.Render(ctx, order) //!issue:2
		}
		if err == nil {
			err = h.mailer.Send(ctx, order.CustomerEmail, "Your receipt", pdf) //!issue:2
		}
		if err == nil {
			err = h.fulfillment.CreateShipment(ctx, order) //!issue:2
		}
		if err != nil {
			http.Error(w, "processing failed", http.StatusInternalServerError)
			return
		}
	default:
		http.Error(w, "unhandled event "+event.Type, http.StatusBadRequest) //!issue:4
		return
	}
	w.WriteHeader(http.StatusOK)
}

