pub async fn payments_webhook(
    State(app): State<AppState>,
    headers: HeaderMap,
    Json(event): Json<ProviderEvent>,
) -> StatusCode {
    let header = headers.get("X-Signature").and_then(|v| v.to_str().ok()).unwrap_or("");
    let sig: HashMap<&str, &str> = header.split(',').filter_map(|p| p.split_once('=')).collect();
    let canonical = serde_json::to_string(&event).unwrap(); //!issue:1
    let mut mac = Hmac::<Sha256>::new_from_slice(&app.webhook_secret).unwrap();
    mac.update(format!("{}.{}", sig.get("t").unwrap_or(&""), canonical).as_bytes()); //!issue:1
    if hex::encode(mac.finalize().into_bytes()) != *sig.get("v1").unwrap_or(&"") { //!issue:1
        return StatusCode::UNAUTHORIZED;
    }
    match event.kind.as_str() {
        "payment.succeeded" => { //!issue:3
            let result: Result<(), AppError> = async {
                let order = app.orders.mark_paid(&event.data.order_id, event.data.amount).await?;
                let pdf = app.invoices.render(&order).await?; //!issue:2
                app.mailer.send(&order.customer_email, "Your receipt", vec![pdf]).await?; //!issue:2
                app.fulfillment.create_shipment(&order).await //!issue:2
            }
            .await;
            if result.is_err() {
                return StatusCode::INTERNAL_SERVER_ERROR;
            }
        }
        other => {
            tracing::warn!(event_type = other, "unhandled webhook event");
            return StatusCode::BAD_REQUEST; //!issue:4
        }
    }
    StatusCode::OK
}

