@PostMapping("/webhooks/payments")
public ResponseEntity<String> paymentsWebhook(@RequestHeader("X-Signature") String header,
                                              @RequestBody ProviderEvent event) throws Exception {
    Map<String, String> sig = Arrays.stream(header.split(","))
        .map(p -> p.split("=", 2)).filter(kv -> kv.length == 2)
        .collect(Collectors.toMap(kv -> kv[0], kv -> kv[1]));
    String canonical = objectMapper.writeValueAsString(event); //!issue:1
    Mac mac = Mac.getInstance("HmacSHA256");
    mac.init(new SecretKeySpec(webhookSecret, "HmacSHA256"));
    byte[] digest = mac.doFinal((sig.get("t") + "." + canonical).getBytes(StandardCharsets.UTF_8)); //!issue:1
    if (!HexFormat.of().formatHex(digest).equals(sig.get("v1"))) { //!issue:1
        return ResponseEntity.status(401).build();
    }
    switch (event.type()) {
        case "payment.succeeded" -> { //!issue:3
            Order order = orders.markPaid(event.data().orderId(), event.data().amount());
            byte[] pdf = invoices.render(order); //!issue:2
            mailer.send(order.customerEmail(), "Your receipt", pdf); //!issue:2
            fulfillment.createShipment(order); //!issue:2
        }
        default -> {
            return ResponseEntity.badRequest().body("unhandled event " + event.type()); //!issue:4
        }
    }
    return ResponseEntity.ok().build();
}

