type load struct {
	done chan struct{}
	val  *Product
	err  error
}

type ProductCache struct {
	catalog CatalogDB
	mu      sync.Mutex
	loads   map[string]*load //!issue:3
}

func (c *ProductCache) Get(ctx context.Context, tenantID, productID int64) (*Product, error) {
	key := strconv.FormatInt(tenantID, 10) + strconv.FormatInt(productID, 10) //!issue:2
	c.mu.Lock()
	l, ok := c.loads[key]
	if !ok {
		l = &load{done: make(chan struct{})}
		c.loads[key] = l //!issue:1,3
		c.mu.Unlock()
		l.val, l.err = c.catalog.GetProduct(context.Background(), tenantID, productID) //!issue:1,4
		close(l.done)
	} else {
		c.mu.Unlock()
	}
	<-l.done //!issue:4
	return l.val, l.err
}

func (c *ProductCache) UpdatePrice(ctx context.Context, tenantID, productID, priceCents int64) error {
	if err := c.catalog.UpdatePrice(ctx, tenantID, productID, priceCents); err != nil {
		return err
	}
	c.mu.Lock()
	delete(c.loads, strconv.FormatInt(tenantID, 10)+strconv.FormatInt(productID, 10)) //!issue:2,3
	c.mu.Unlock()
	return nil
}

