        let load = {
            let mut loads = self.loads.lock().unwrap();
            loads
                .entry(key) //!issue:1,3
                .or_insert_with(|| {
                    let catalog = Arc::clone(&self.catalog);
                    async move {
                        catalog.get_product(tenant_id, product_id).await //!issue:1,4
                            .map(|p| p.map(Arc::new))
                            .map_err(Arc::new)
